import functools


def multiply(a, b):
    return a * b


def product(numbers):
    return functools.reduce(multiply, numbers, 1)


double = functools.partial(multiply, 2)


@functools.lru_cache
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)
